// Slots de vitrina desbloqueados por nivel
function showcaseSlotsForLevel(level) {
  if (level >= 20) return 7;
  if (level >= 15) return 5;
  if (level >= 10) return 3;
  if (level >= 5)  return 1;
  return 0;
}

