function xpForLevel(level) {
  return Math.floor(100 * Math.pow(1.30, level - 1));
}

function levelRewards(level) {
  const r = [{ type:'money', amount: level * 75 + 100 }];
  if (level % 5  === 0) r.push({ type:'bodega', id:'estandar' });
  if (level % 10 === 0) r.push({ type:'bodega', id:'premium' });
  if (level % 20 === 0) r.push({ type:'bodega', id:'rara' });
  return r;
}
